#!/usr/bin/env node
/**
 * N137 · G1 the asset lint (v7 UX plan r3, `04` §3.3). For every entry of assets.manifest.json it checks that:
 *  - the file exists and is within its byte budget;
 *  - a PNG has the size the manifest names;
 *  - a committed generated file is exactly what its generator writes today (the Android icons and colours), so no
 *    asset can drift from its source;
 * and, for the mark itself, that the ℓ on the paper is at least 7 : 1 and the ∎ at least 3 : 1 in Day and Night.
 * Runs after every build (`postbuild`); wiring it into CI as its own check is an Owner `rules:` PR.
 */
import {existsSync, readFileSync, statSync} from 'node:fs';
import {join, relative} from 'node:path';
import {MARK_THEMES, contrast} from './lemma-mark.mjs';
import {generate as androidIcons} from '../android-icons.mjs';
import {COLOR_FILES, colorsXml, readTokens} from './android-colors.mjs';

const root = process.cwd();

/** Width and height of a PNG, or null when the bytes are not a PNG. */
export function pngSize(bytes) {
  if (bytes.length < 24 || bytes.toString('hex', 0, 8) !== '89504e470d0a1a0a') return null;
  return [bytes.readUInt32BE(16), bytes.readUInt32BE(20)];
}

/** What each committed generator would write right now, keyed by repository path. */
export function expectedOutputs() {
  const files = new Map();
  androidIcons((path, data) => files.set(relative(root, path), Buffer.from(data)));
  const tokens = readTokens();
  for (const [mode, path] of Object.entries(COLOR_FILES)) files.set(relative(root, path), Buffer.from(colorsXml(tokens, mode)));
  return files;
}

/** Problems with the manifest's entries, as plain sentences; empty when everything holds. */
export function lintAssets(manifest, {read = path => existsSync(join(root, path)) ? readFileSync(join(root, path)) : null,
  expected = expectedOutputs()} = {}) {
  const problems = [];
  const listed = new Set();
  for (const entry of manifest.assets) {
    listed.add(entry.path);
    const bytes = read(entry.path);
    if (!bytes) {problems.push(`${entry.path}: missing (run ${entry.generator})`); continue;}
    if (bytes.length > entry.budget) problems.push(`${entry.path}: ${bytes.length} bytes, over its ${entry.budget}-byte budget`);
    if (entry.size) {
      const size = pngSize(bytes);
      if (!size) problems.push(`${entry.path}: not a PNG`);
      else if (size[0] !== entry.size[0] || size[1] !== entry.size[1]) problems.push(`${entry.path}: ${size.join('×')}, expected ${entry.size.join('×')}`);
    }
    const want = expected.get(entry.path);
    if (entry.generated === 'committed' && want && !want.equals(bytes)) problems.push(`${entry.path}: differs from what ${entry.generator} writes; run it and commit the result`);
  }
  for (const path of expected.keys()) if (!listed.has(path)) problems.push(`${path}: generated by a committed generator but not listed in assets.manifest.json`);
  const {ellOnPage, qedOnPage} = manifest.checks.markContrast;
  for (const [theme, colours] of Object.entries(MARK_THEMES)) {
    const ell = contrast(colours.ink, colours.page), qed = contrast(colours.brand, colours.page);
    if (ell < ellOnPage) problems.push(`mark (${theme}): ℓ on paper is ${ell.toFixed(2)} : 1, below ${ellOnPage} : 1`);
    if (qed < qedOnPage) problems.push(`mark (${theme}): ∎ on paper is ${qed.toFixed(2)} : 1, below ${qedOnPage} : 1`);
  }
  return problems;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const manifest = JSON.parse(readFileSync(join(root, 'assets.manifest.json'), 'utf8'));
  const problems = lintAssets(manifest);
  if (problems.length) {
    console.error('Asset lint: ' + problems.length + ' problem(s)\n - ' + problems.join('\n - '));
    process.exit(1);
  }
  const bytes = manifest.assets.reduce((sum, entry) => sum + statSync(join(root, entry.path)).size, 0);
  console.log(`Asset lint: ${manifest.assets.length} assets OK (${Math.round(bytes / 1024)} KB), mark contrast OK in Day and Night`);
}
